-- 47_predictionsml.sql — SDBI B-10b m3 import: legacy RTL predictive-analytics cluster -> 2 sys.* tables (S973).
-- READ MODEL: legacy precomputed predictive values imported AS-IS (no in-platform ML, no recomputation).
-- RTL-only (legacy tenant 0c54b84a -> v5 RTL 86ba7a65). Employee-centric (I14):
--   subject employee_id (model_predictions.entity_id / performance_predictions.employee_id /
--     turnover_risk_scores.employee_id) = legacy employees.id -> bridged via
--     sys_users.user_external_code='LEGACY_EMP::'||employee_id; unresolved -> FK NULL + legacy id in metadata.
--   model FK = legacy predictive_models.id -> bridged via model_natural_key='LEGACY_PMODEL::'||model_id;
--     unresolved legacy model (e.g. cross-tenant model_id) -> FK NULL + legacy id in metadata.
-- Folds 3 legacy precomputed prediction tables into typed rows of sys_model_predictions:
--   model_predictions       -> prediction_type='GENERIC'     (model FK resolvable when model is RTL)
--   performance_predictions -> prediction_type='PERFORMANCE' (no FK to predictive_models in legacy -> NULL)
--   turnover_risk_scores    -> prediction_type='TURNOVER'    (no FK to predictive_models in legacy -> NULL)
-- The legacy recompute-VIEW mv_talent_signals is INTENTIONALLY NOT imported (inline-CASE recompute that
--   overlaps the existing sys.sys_talent_scores, 154 rows; sys_talent_scores left untouched).
-- Sibling pattern: 46_engagement_surveys.sql. Data baked as VALUES (CI-reproducible). Idempotent:
--   ON CONFLICT (tenant, natural_key) DO NOTHING.
-- Expected landed (RTL): models 4 / predictions 468 (156 GENERIC + 156 PERFORMANCE + 156 TURNOVER).
--   All 156 distinct subject employees resolve in sys_users (0 unresolved on this RTL slice).
--   GENERIC rows reference legacy model_id 81a3c97f (Heuresys System tenant's Turnover Risk Model) which is
--     NOT in the RTL slice -> prediction_model_id resolves to NULL (legacy id preserved in metadata).
-- Source-vs-target: legacy cluster total = 16 models / 267+267+267 predictions across 4 tenants;
--   this seed imports the RTL slice only (mirrors 46_engagement_surveys RTL-only scope). Non-RTL tenants
--   (1d7bf448 SmartFood / fb1e866c EcoNova / d5855519 Heuresys System) have no v5 tenancy mapping -> SKIPPED:
--   12 models + 333 predictions/table = 12 models + 999 predictions not imported (cannot be tenant-assigned).
-- valid_until ~2026-01-11 (already past) -> historical point-in-time read-model; provenance preserved in
--   prediction_computed_at / prediction_valid_until.
BEGIN;

-- §1 — models (registry; immutable read-model)
WITH src(lid,name,mtype,version,algorithm,target,status,accuracy,metadata) AS (VALUES
