  ('0a55cd97-e995-4efb-831c-aead223c7e35','Skill Gap Analyzer','clustering','1','kmeans','skill_gap_cluster','active','{"inertia": 1250.5, "silhouette_score": 0.65}'::jsonb,'{"features": ["skill_proficiency_avg", "skill_count", "skill_demand_alignment", "training_completion_rate"], "is_active": true, "description": "Clusters employees by skill gaps", "hyperparameters": {"n_init": 10, "max_iter": 300, "n_clusters": 5}, "last_trained_at": "2025-11-19T19:02:36.463461+00:00", "training_config": {"train_split": 1.0}}'::jsonb),
  ('9e1d3db7-3e0f-478f-9904-6c0b8a6f563e','Performance Predictor','regression','1','gradient_boosting','performance_rating','active','{"mae": 0.28, "rmse": 0.35, "r2_score": 0.78}'::jsonb,'{"features": ["skills_count", "training_hours", "tenure_months", "goal_completion_rate", "engagement_score"], "is_active": true, "description": "Predicts expected performance rating", "hyperparameters": {"max_depth": 6, "n_estimators": 150, "learning_rate": 0.1}, "last_trained_at": "2025-11-17T08:14:45.053609+00:00", "training_config": {"test_split": 0.1, "train_split": 0.8, "validation_split": 0.1}}'::jsonb)
)
INSERT INTO sys.sys_predictive_models
  (model_tenant_id, model_natural_key, model_name, model_type, model_version, model_algorithm,
   model_target_variable, model_status, model_accuracy_metrics, model_metadata)
SELECT '86ba7a65-217f-48ba-8ce5-5c09b40a66b0'::uuid, 'LEGACY_PMODEL::'||src.lid, src.name, src.mtype,
  src.version, NULLIF(src.algorithm,''), NULLIF(src.target,''), src.status, src.accuracy,
  src.metadata || jsonb_build_object('legacy_model_id', src.lid)
FROM src
ON CONFLICT (model_tenant_id, model_natural_key) DO NOTHING;

