INSERT INTO sys.sys_model_predictions
  (prediction_tenant_id, prediction_natural_key, prediction_model_id, prediction_subject_user_id,
   prediction_type, prediction_value, prediction_label, prediction_confidence, prediction_details,
   prediction_valid_until, prediction_computed_at, prediction_metadata)
SELECT '86ba7a65-217f-48ba-8ce5-5c09b40a66b0'::uuid, 'LEGACY_MPRED::'||src.lid, m.model_id, subj.user_id,
  'GENERIC', src.value::numeric, src.label::varchar, src.confidence::numeric, COALESCE(src.details,'{}'::jsonb),
  src.valid_until::timestamptz, src.computed_at::timestamptz,
  jsonb_strip_nulls(jsonb_build_object('legacy_prediction_id', src.lid, 'source_table', 'model_predictions',
    'legacy_employee_id', src.subject_emp_lid, 'legacy_model_id', src.model_lid,
    'unresolved_model', CASE WHEN m.model_id IS NULL THEN src.model_lid END,
    'unresolved_subject', CASE WHEN subj.user_id IS NULL THEN src.subject_emp_lid END))
FROM src
LEFT JOIN sys.sys_predictive_models m ON m.model_natural_key='LEGACY_PMODEL::'||src.model_lid AND m.model_tenant_id='86ba7a65-217f-48ba-8ce5-5c09b40a66b0'::uuid
LEFT JOIN sys.sys_users subj ON subj.user_external_code='LEGACY_EMP::'||src.subject_emp_lid
ON CONFLICT (prediction_tenant_id, prediction_natural_key) DO NOTHING;

