INSERT INTO sys.sys_model_predictions
  (prediction_tenant_id, prediction_natural_key, prediction_model_id, prediction_subject_user_id,
   prediction_type, prediction_value, prediction_label, prediction_confidence, prediction_details,
   prediction_valid_until, prediction_computed_at, prediction_metadata)
SELECT '86ba7a65-217f-48ba-8ce5-5c09b40a66b0'::uuid, 'LEGACY_TRISK::'||src.lid, NULL::uuid, subj.user_id,
  'TURNOVER', src.value::numeric, src.label::varchar, src.confidence::numeric, COALESCE(src.details,'{}'::jsonb),
  src.valid_until::timestamptz, src.computed_at::timestamptz,
  jsonb_strip_nulls(jsonb_build_object('legacy_prediction_id', src.lid, 'source_table', 'turnover_risk_scores',
    'legacy_employee_id', src.subject_emp_lid,
    'unresolved_subject', CASE WHEN subj.user_id IS NULL THEN src.subject_emp_lid END))
FROM src
LEFT JOIN sys.sys_users subj ON subj.user_external_code='LEGACY_EMP::'||src.subject_emp_lid
ON CONFLICT (prediction_tenant_id, prediction_natural_key) DO NOTHING;

-- §5 — reconciliation registry (classify the 2 new tables; status POPULATED resolves live via has_rows)
INSERT INTO sys.sys_reconciliation_registry
  (reconciliation_registry_table_name, reconciliation_registry_bucket, reconciliation_registry_declared_status,
   reconciliation_registry_legacy_source, reconciliation_registry_legacy_source_rows, reconciliation_registry_rationale)
VALUES
  ('sys_predictive_models','A','IMPORT','predictive_models',16,'[S973 SDBI m3] Predictive-model registry (read-model); RTL-only import (4 of 16 legacy rows). No in-platform ML.'),
  ('sys_model_predictions','A','IMPORT','model_predictions',267,'[S973 SDBI m3] Generic typed prediction read-model folding model_predictions + performance_predictions + turnover_risk_scores; RTL-only (468 = 156x3 of 801 across 3 source tables); legacy precomputed values imported as-is. mv_talent_signals intentionally NOT imported (recompute-view overlapping sys_talent_scores).')
ON CONFLICT (reconciliation_registry_table_name) DO NOTHING;

DO $post$
DECLARE m int; p int; g int; pf int; tu int; u int;
BEGIN
  SELECT count(*) INTO m FROM sys.sys_predictive_models;
  SELECT count(*) INTO p FROM sys.sys_model_predictions;
  SELECT count(*) INTO g  FROM sys.sys_model_predictions WHERE prediction_type='GENERIC';
  SELECT count(*) INTO pf FROM sys.sys_model_predictions WHERE prediction_type='PERFORMANCE';
  SELECT count(*) INTO tu FROM sys.sys_model_predictions WHERE prediction_type='TURNOVER';
  SELECT count(*) INTO u  FROM sys.sys_model_predictions WHERE prediction_subject_user_id IS NULL;
  RAISE NOTICE '47_predictionsml: models=% predictions=% (G=% P=% T=%) (expect 4/468/156/156/156); unresolved subjects=% (expect 0)', m, p, g, pf, tu, u;
  IF m<>4 OR p<>468 OR g<>156 OR pf<>156 OR tu<>156 THEN
    RAISE EXCEPTION '47_predictionsml: count mismatch m=% p=% g=% pf=% tu=%', m, p, g, pf, tu;
  END IF;
END $post$;
COMMIT;
